function createBoardStore(doc: Y.Doc): BoardStore {
  initDoc(doc);
  const listeners = new Set<() => void>();
  let cached: readonly StickySnapshot[] = snapshot(doc);
  let attached = false;
  const notify = () => { cached = snapshot(doc); for (const l of listeners) l(); };
  return {
    doc,
    subscribe(onChange) {
      listeners.add(onChange);
      if (!attached) { doc.getMap(OBJECTS_KEY).observeDeep(notify); attached = true; }
      // catch changes that happened before subscribing
      cached = snapshot(doc);
      return () => { listeners.delete(onChange); if (listeners.size === 0) { doc.getMap(OBJECTS_KEY).unobserveDeep(notify); attached = false; } };
    },
    getSnapshot() { return cached; },
  };
}
